//! One physical admission chooses A transition or the ordinary fresh/current B path.
use super::super::{opening, refusal::*, request::*, runtime::*};
use super::{plan::*, refusal::*, request::*};
use worth_query_declaration::facade::{application_program::*, application_schema::*};
use worth_query_execution::facade::{
    application_contribution::*, application_home_integration::*, application_installation::*,
};
use worth_store_application::*;

impl<'a, A, AP, B, BP, Author>
    WorthQueryApplicationHomeRequest<'a, B, BP, WorthQueryHomeProgramTransition<'a, A, AP, Author>>
where
    A: ApplicationSchemaComposition,
    AP: ApplicationProgramDefinition<A> + 'static,
    AP::Outputs: ApplicationProgramOutputsShape<A> + WorthQueryApplicationProgramRoots<A>,
    AP::Contributions: WorthQueryApplicationContributionTuple<A>,
    B: ApplicationSchemaComposition,
    BP: ApplicationProgramDefinition<B> + 'static,
    BP::Outputs: ApplicationProgramOutputsShape<B> + WorthQueryApplicationProgramRoots<B>,
    BP::Contributions: WorthQueryApplicationContributionTuple<B>,
    Author: FnOnce(
        &WorthQueryHomeProgramTransitionReadSource<'_, '_>,
        &WorthQueryHomeProgramTransitionTarget<'_>,
    ) -> Result<
        WorthQueryHomeProgramTransitionPlan,
        worth_query_execution::facade::primary_graph::WorthQueryPrimaryGraphInstallationDenial,
    >,
{
    #[inline(never)]
    pub fn open_in_advancement(
        self,
        phase: &WorthQueryBootstrapAdvancementPhase<'_>,
    ) -> Result<
        WorthQueryApplicationHome<B, BP>,
        WorthQueryHomeProgramTransitionOpenRefused<A, AP, B, BP>,
    > {
        self.prepare_transition_opening(phase)?.finish(phase)
    }

    #[inline(never)]
    fn prepare_transition_opening(
        self,
        phase: &WorthQueryBootstrapAdvancementPhase<'_>,
    ) -> Result<
        Box<PreparedHomeProgramOpening<'a, A, AP, B, BP, Author>>,
        WorthQueryHomeProgramTransitionOpenRefused<A, AP, B, BP>,
    > {
        use WorthQueryHomeProgramTransitionDenial as Denial;
        use WorthQueryHomeProgramTransitionOpenRefused as Refused;
        let WorthQueryHomeProgramTransition {
            predecessor,
            author,
            resources,
        } = self.transition;
        let WorthQueryApplicationHomeLocation::Directory(location) = self.location else {
            return Err(Refused::configuration(Denial::DirectoryRequired));
        };
        if [
            resources.maximum_work_units,
            resources.maximum_cold_record_slots,
            resources.maximum_derived_rows,
        ]
        .iter()
        .any(|limit| !matches!(limit, Some(1..)))
        {
            return Err(Refused::configuration(Denial::FiniteResourcesRequired));
        }
        let after = prepare_home_program(
            self.program,
            self.roster,
            self.declaration,
            self.configuration,
            self.build,
            self.limits,
            self.authorization_time_source,
            super::super::support::directory_requirement_refusal,
        )
        .map_err(|cause| {
            Refused::successor(WorthQueryApplicationHomeOpenRefused::Preparation(cause))
        })?;
        let before = prepare_home_program(
            predecessor.program,
            predecessor.roster,
            predecessor.declaration,
            predecessor.configuration,
            predecessor.build,
            predecessor.limits,
            predecessor.authorization_time_source,
            super::super::support::directory_requirement_refusal,
        );
        let before = match before {
            Ok(before) => before,
            Err(cause) => {
                return Err(Refused::predecessor(
                    WorthQueryApplicationHomeOpenRefused::Preparation(cause),
                    after,
                ))
            }
        };
        let binding = match after.admitted_home_binding() {
            Ok(binding) => binding,
            Err(cause) => {
                return Err(Refused::successor(
                    WorthQueryApplicationHomeOpenRefused::Binding {
                        query: after,
                        cause,
                    },
                ))
            }
        };
        let predecessor = match before.admitted_home_binding() {
            Ok(binding) => binding,
            Err(cause) => {
                return Err(Refused::predecessor(
                    WorthQueryApplicationHomeOpenRefused::Binding {
                        query: before,
                        cause,
                    },
                    after,
                ))
            }
        };
        let mut physical = ApplicationHomeRequest::new(
            location,
            after.home_relational_definition(),
            binding,
            self.build,
        )
        .with_program_transition_predecessor(before.home_relational_definition(), predecessor);
        let observation = self
            .opening_control
            .as_ref()
            .map(|control| control.observation())
            .unwrap_or_default();
        if let Some(control) = self.opening_control {
            physical = physical.with_opening_control_for_test(control);
        }
        let request = phase.execution_request();
        let admitted =
            match recover_home(physical, &request).and_then(|home| admit_home(home, &request)) {
                Ok(home) => home,
                Err(cause) => {
                    return Err(Refused::successor(
                        WorthQueryApplicationHomeOpenRefused::Physical {
                            query: after,
                            cause,
                        },
                    ))
                }
            };
        Ok(Box::new(match select_home_program_opening(admitted) {
            ApplicationHomeProgramOpening::Current(home) => {
                drop((before, author));
                PreparedHomeProgramOpening::Current {
                    query: after,
                    home,
                    checkpoint_limits: self.checkpoint_limits,
                    observation,
                    initial_state: self.initial_state,
                }
            }
            ApplicationHomeProgramOpening::TransitionRequired(home) => {
                PreparedHomeProgramOpening::Transition {
                    before,
                    after,
                    home,
                    author,
                    resources,
                    checkpoint_limits: self.checkpoint_limits,
                    observation,
                }
            }
        }))
    }
}

// Each owned phase is consumed before its successor's stack frames begin.
enum PreparedHomeProgramOpening<
    'a,
    A: ApplicationSchemaComposition,
    AP,
    B: ApplicationSchemaComposition,
    BP,
    Author,
> {
    Current {
        query: PreparedHomeApplication<B, BP>, home: worth_proof::HomeAdmitted<AdmittedApplicationHome>,
        checkpoint_limits: ApplicationHomeCheckpointLimits, observation: ApplicationHomeOpeningObservation,
        initial_state: Box<dyn FnOnce(&WorthQueryBootstrapAdvancementPhase<'_>, &mut worth_query_execution::facade::primary_graph::WorthQueryPrimaryGraphBootstrap<B>, &worth_query_installation::facade::WorthQueryInstalledApplicationSchema<B>) -> Result<(), worth_query_execution::facade::primary_graph::WorthQueryPrimaryGraphInstallationDenial> + 'a>,
    },
    Transition {
        before: PreparedHomeApplication<A, AP>, after: PreparedHomeApplication<B, BP>,
        home: worth_proof::HomeAdmitted<AdmittedApplicationHome>, author: Author,
        resources: worth_relational::facade::indexes::DerivedIndexMaintenanceBudget,
        checkpoint_limits: ApplicationHomeCheckpointLimits, observation: ApplicationHomeOpeningObservation,
    },
}
enum ReadyHomeProgramOpening<
    'a,
    A: ApplicationSchemaComposition,
    AP,
    B: ApplicationSchemaComposition,
    BP,
    Author,
> {
    Current(opening::preparation::DirectoryOpening<'a, B, BP>),
    Transition {
        before: ReadmittedExistingHomeNativeMeaning<A, AP>,
        after: PreparedHomeApplication<B, BP>,
        home: UnsharedReadmittedApplicationHome,
        author: Author,
        resources: worth_relational::facade::indexes::DerivedIndexMaintenanceBudget,
        checkpoint_limits: ApplicationHomeCheckpointLimits,
        observation: ApplicationHomeOpeningObservation,
    },
}
impl<'a, A, AP, B, BP, Author> PreparedHomeProgramOpening<'a, A, AP, B, BP, Author>
where
    A: ApplicationSchemaComposition,
    AP: ApplicationProgramDefinition<A> + 'static,
    AP::Outputs: ApplicationProgramOutputsShape<A> + WorthQueryApplicationProgramRoots<A>,
    AP::Contributions: WorthQueryApplicationContributionTuple<A>,
    B: ApplicationSchemaComposition,
    BP: ApplicationProgramDefinition<B> + 'static,
    BP::Outputs: ApplicationProgramOutputsShape<B> + WorthQueryApplicationProgramRoots<B>,
    BP::Contributions: WorthQueryApplicationContributionTuple<B>,
    Author: FnOnce(
        &WorthQueryHomeProgramTransitionReadSource<'_, '_>,
        &WorthQueryHomeProgramTransitionTarget<'_>,
    ) -> Result<
        WorthQueryHomeProgramTransitionPlan,
        worth_query_execution::facade::primary_graph::WorthQueryPrimaryGraphInstallationDenial,
    >,
{
    #[inline(never)]
    fn finish(
        self: Box<Self>,
        phase: &WorthQueryBootstrapAdvancementPhase<'_>,
    ) -> Result<
        WorthQueryApplicationHome<B, BP>,
        WorthQueryHomeProgramTransitionOpenRefused<A, AP, B, BP>,
    > {
        self.readmit(phase)?.finish(phase)
    }
    #[inline(never)]
    fn readmit(
        self: Box<Self>,
        phase: &WorthQueryBootstrapAdvancementPhase<'_>,
    ) -> Result<
        Box<ReadyHomeProgramOpening<'a, A, AP, B, BP, Author>>,
        WorthQueryHomeProgramTransitionOpenRefused<A, AP, B, BP>,
    > {
        use WorthQueryHomeProgramTransitionOpenRefused as Refused;
        match *self {
            Self::Current {
                query,
                home,
                checkpoint_limits,
                observation,
                initial_state,
            } => {
                let (query, home) = opening::preparation::readmit_native(phase, query, home)
                    .map_err(Refused::successor)?;
                Ok(Box::new(ReadyHomeProgramOpening::Current(
                    opening::preparation::DirectoryOpening {
                        query,
                        home,
                        checkpoint_limits,
                        observation,
                        initial_state,
                    },
                )))
            }
            Self::Transition {
                before,
                after,
                home,
                author,
                resources,
                checkpoint_limits,
                observation,
            } => {
                let (query, home) = match opening::preparation::readmit_native(phase, before, home)
                {
                    Ok(parts) => parts,
                    Err(refused) => return Err(Refused::predecessor(refused, after)),
                };
                let (before, home) = match opening::existing::finalize_native(phase, home, query) {
                    Ok(parts) => parts,
                    Err(refused) => return Err(Refused::predecessor(refused, after)),
                };
                Ok(Box::new(ReadyHomeProgramOpening::Transition {
                    before,
                    after,
                    home,
                    author,
                    resources,
                    checkpoint_limits,
                    observation,
                }))
            }
        }
    }
}
impl<A, AP, B, BP, Author> ReadyHomeProgramOpening<'_, A, AP, B, BP, Author>
where
    A: ApplicationSchemaComposition,
    AP: ApplicationProgramDefinition<A> + 'static,
    AP::Outputs: ApplicationProgramOutputsShape<A> + WorthQueryApplicationProgramRoots<A>,
    AP::Contributions: WorthQueryApplicationContributionTuple<A>,
    B: ApplicationSchemaComposition,
    BP: ApplicationProgramDefinition<B> + 'static,
    BP::Outputs: ApplicationProgramOutputsShape<B> + WorthQueryApplicationProgramRoots<B>,
    BP::Contributions: WorthQueryApplicationContributionTuple<B>,
    Author: FnOnce(
        &WorthQueryHomeProgramTransitionReadSource<'_, '_>,
        &WorthQueryHomeProgramTransitionTarget<'_>,
    ) -> Result<
        WorthQueryHomeProgramTransitionPlan,
        worth_query_execution::facade::primary_graph::WorthQueryPrimaryGraphInstallationDenial,
    >,
{
    #[inline(never)]
    fn finish(
        self: Box<Self>,
        phase: &WorthQueryBootstrapAdvancementPhase<'_>,
    ) -> Result<
        WorthQueryApplicationHome<B, BP>,
        WorthQueryHomeProgramTransitionOpenRefused<A, AP, B, BP>,
    > {
        match *self {
            Self::Current(opening) => opening::initialization::initialize_directory(phase, opening)
                .map_err(WorthQueryHomeProgramTransitionOpenRefused::successor),
            Self::Transition {
                before,
                after,
                home,
                author,
                resources,
                checkpoint_limits,
                observation,
            } => super::handoff::transition(
                phase,
                before,
                after,
                home,
                author,
                resources,
                checkpoint_limits,
                observation,
            ),
        }
    }
}

//! Original Query custody is admitted before World seal and retained afterward.
use super::runtime::*;
use worth_execution::ExecutionRequest;
use worth_query_declaration::facade::application_schema::ApplicationSchema;
use worth_query_execution::facade::{
    application_installation::{
        WorthQueryPreparedHomeQuery, WorthQueryProgramApplicationRuntime,
        WorthQueryRetiredHomeQuery, WorthQueryRetiringHomeQuery,
    },
    primary_graph::WorthQueryHomeRetirementDenial,
};
use worth_store_application::*;
mod maintenance;
mod retirement;
mod retry;

pub struct WorthQueryApplicationHomeClosed {
    outcome: ApplicationHomeCloseOutcome,
    retired_query: Option<WorthQueryRetiredHomeQuery>,
}
impl WorthQueryApplicationHomeClosed {
    pub fn is_closed(&self) -> bool {
        matches!(self.outcome, ApplicationHomeCloseOutcome::Closed { .. })
    }
    pub(super) fn into_parts(
        self,
    ) -> (
        ApplicationHomeCloseOutcome,
        Option<WorthQueryRetiredHomeQuery>,
    ) {
        (self.outcome, self.retired_query)
    }
    pub fn outcome(&self) -> &ApplicationHomeCloseOutcome {
        &self.outcome
    }
    /// Arbitrary inert supplier destruction runs only outside budgeted close.
    pub fn reclaim(self) {
        let (outcome, retired_query) = self.into_parts();
        drop(outcome);
        if let Some(retired_query) = retired_query {
            retired_query.reclaim();
        }
    }
}

pub struct WorthQueryApplicationHomeCloseRefused<Schema, Program> {
    custody: CloseCustody<Schema, Program>,
}
enum CloseCustody<Schema, Program> {
    MemoryLifecycleRequired(WorthQueryApplicationHome<Schema, Program>),
    WorldAdmission {
        query: WorthQueryProgramApplicationRuntime<Schema, Program>,
        home: DirectoryHome,
        checkpoint_limits: ApplicationHomeCheckpointLimits,
        cause: ApplicationHomeCloseDenial,
    },
    QueryAdmission {
        query: WorthQueryProgramApplicationRuntime<Schema, Program>,
        home: DirectoryHome,
        checkpoint_limits: ApplicationHomeCheckpointLimits,
        cause: WorthQueryHomeRetirementDenial,
    },
    World {
        query: WorthQueryPreparedHomeQuery<Schema, Program>,
        home: WorldHomeCloseRefused<(), (), (), (), ()>,
        checkpoint_limits: ApplicationHomeCheckpointLimits,
    },
    QueryRetirement {
        query: WorthQueryRetiringHomeQuery<Schema, Program>,
        home: WorldSealedApplicationHome,
        cause: WorthQueryHomeRetirementDenial,
    },
    MaintenanceRetirement {
        query: WorthQueryRetiringHomeQuery<Schema, Program>,
        home: WorldSealedApplicationHome,
        cause: ApplicationHomeCloseDenial,
    },
    QueryReleased {
        cause: ApplicationHomeCloseDenial,
        posture: ApplicationHomeClosePosture,
        retired_query: Option<WorthQueryRetiredHomeQuery>,
    },
}
impl<Schema, Program> std::fmt::Debug for WorthQueryApplicationHomeCloseRefused<Schema, Program> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let mut output = f.debug_struct("WorthQueryApplicationHomeCloseRefused");
        output.field("reason", &self.detail());
        let phase = match &self.custody {
            CloseCustody::MemoryLifecycleRequired(_) => "memory-lifecycle",
            CloseCustody::WorldAdmission { .. } => "world-admission",
            CloseCustody::QueryAdmission { .. } => "query-admission",
            CloseCustody::World { .. } => "world-close",
            CloseCustody::QueryRetirement { .. } => "query-retirement",
            CloseCustody::MaintenanceRetirement { .. } => "maintenance-retirement",
            CloseCustody::QueryReleased { .. } => "physical-close",
        };
        output.field("phase", &phase);
        if let CloseCustody::QueryReleased {
            posture: ApplicationHomeClosePosture::RecoveryRequired(custody),
            ..
        } = &self.custody
        {
            output.field("checkpoint", custody.checkpoint_result());
        }
        output.finish()
    }
}
impl<Schema: ApplicationSchema, Program: 'static> WorthQueryApplicationHome<Schema, Program> {
    pub fn close(
        self,
        request: &ExecutionRequest<'_, '_>,
    ) -> Result<
        WorthQueryApplicationHomeClosed,
        WorthQueryApplicationHomeCloseRefused<Schema, Program>,
    > {
        let Self {
            query,
            directory,
            checkpoint_limits,
        } = self;
        let Some(home) = directory else {
            return Err(WorthQueryApplicationHomeCloseRefused {
                custody: CloseCustody::MemoryLifecycleRequired(Self {
                    query,
                    directory: None,
                    checkpoint_limits,
                }),
            });
        };
        if let Err(cause) = home.preflight_world_close(request) {
            return Err(WorthQueryApplicationHomeCloseRefused {
                custody: CloseCustody::WorldAdmission {
                    query,
                    home,
                    checkpoint_limits,
                    cause,
                },
            });
        }
        let query = match query.prepare_home_retirement(request) {
            Ok(query) => query,
            Err((query, cause)) => {
                return Err(WorthQueryApplicationHomeCloseRefused {
                    custody: CloseCustody::QueryAdmission {
                        query,
                        home,
                        checkpoint_limits,
                        cause,
                    },
                })
            }
        };
        // No supplier callback occurs under World's final logical admission gates.
        match home.seal_world(request) {
            Ok(home) => retirement::finish_after_world(query, home, request),
            Err(home) => Err(WorthQueryApplicationHomeCloseRefused {
                custody: CloseCustody::World {
                    query,
                    home,
                    checkpoint_limits,
                },
            }),
        }
    }
}
impl<Schema, Program> WorthQueryApplicationHomeCloseRefused<Schema, Program> {
    pub fn directory_denial(&self) -> Option<&ApplicationHomeCloseDenial> {
        match &self.custody {
            CloseCustody::World { home, .. } => Some(home.reason()),
            CloseCustody::WorldAdmission { cause, .. } => Some(cause),
            CloseCustody::QueryReleased { cause, .. } => Some(cause),
            CloseCustody::MaintenanceRetirement { cause, .. } => Some(cause),
            _ => None,
        }
    }
    pub fn query_denial(&self) -> Option<&WorthQueryHomeRetirementDenial> {
        match &self.custody {
            CloseCustody::QueryAdmission { cause, .. }
            | CloseCustody::QueryRetirement { cause, .. } => Some(cause),
            _ => None,
        }
    }
    pub fn detail(&self) -> String {
        match &self.custody {
            CloseCustody::MemoryLifecycleRequired(_) => {
                "memory Home World lifecycle has not been readmitted".to_owned()
            }
            CloseCustody::World { home, .. } => format!("{:?}", home.reason()),
            CloseCustody::WorldAdmission { cause, .. } => format!("{cause:?}"),
            CloseCustody::QueryAdmission { cause, .. }
            | CloseCustody::QueryRetirement { cause, .. } => format!("{cause:?}"),
            CloseCustody::QueryReleased { cause, .. } => format!("{cause:?}"),
            CloseCustody::MaintenanceRetirement { cause, .. } => format!("{cause:?}"),
        }
    }
}
impl<Schema: ApplicationSchema, Program> WorthQueryApplicationHomeCloseRefused<Schema, Program> {
    /// Only actual pre-seal custody may restore the original Query service.
    pub fn resume(self) -> Result<WorthQueryApplicationHome<Schema, Program>, Self> {
        match self.custody {
            CloseCustody::MemoryLifecycleRequired(home) => Ok(home),
            CloseCustody::WorldAdmission {
                query,
                home,
                checkpoint_limits,
                cause: _,
            } => Ok(WorthQueryApplicationHome {
                query,
                directory: Some(home),
                checkpoint_limits,
            }),
            CloseCustody::QueryAdmission {
                query,
                home,
                checkpoint_limits,
                cause: _,
            } => Ok(WorthQueryApplicationHome {
                query,
                directory: Some(home),
                checkpoint_limits,
            }),
            CloseCustody::World {
                query,
                home,
                checkpoint_limits,
            } => match home.resume() {
                Ok(home) => Ok(WorthQueryApplicationHome {
                    query: query.resume(),
                    directory: Some(home),
                    checkpoint_limits,
                }),
                Err(home) => Err(Self {
                    custody: CloseCustody::World {
                        query,
                        home,
                        checkpoint_limits,
                    },
                }),
            },
            custody => Err(Self { custody }),
        }
    }
}

pub(super) fn classify_released_query<Schema, Program>(
    outcome: ApplicationHomeCloseOutcome,
    retired_query: Option<WorthQueryRetiredHomeQuery>,
) -> Result<WorthQueryApplicationHomeClosed, WorthQueryApplicationHomeCloseRefused<Schema, Program>>
{
    match outcome {
        outcome @ ApplicationHomeCloseOutcome::Closed { .. } => {
            Ok(WorthQueryApplicationHomeClosed {
                outcome,
                retired_query,
            })
        }
        ApplicationHomeCloseOutcome::CloseRefused { reason, posture } => {
            Err(WorthQueryApplicationHomeCloseRefused {
                custody: CloseCustody::QueryReleased {
                    cause: reason,
                    posture,
                    retired_query,
                },
            })
        }
    }
}

//! Retry retained close custody without replaying preflight or Query service.
use super::*;

impl<Schema: ApplicationSchema, Program: 'static>
    WorthQueryApplicationHomeCloseRefused<Schema, Program>
{
    pub fn try_close(
        self,
        request: &ExecutionRequest<'_, '_>,
    ) -> Result<WorthQueryApplicationHomeClosed, Self> {
        match self.custody {
            CloseCustody::MemoryLifecycleRequired(home) => home.close(request),
            CloseCustody::WorldAdmission {
                query,
                home,
                checkpoint_limits,
                cause: _,
            } => WorthQueryApplicationHome {
                query,
                directory: Some(home),
                checkpoint_limits,
            }
            .close(request),
            CloseCustody::QueryAdmission {
                query,
                home,
                checkpoint_limits,
                cause: _,
            } => WorthQueryApplicationHome {
                query,
                directory: Some(home),
                checkpoint_limits,
            }
            .close(request),
            CloseCustody::World {
                query,
                home,
                checkpoint_limits,
            } => match home.try_seal_world(request) {
                Ok(home) => retirement::finish_after_world(query, home, request),
                Err(home) => Err(Self {
                    custody: CloseCustody::World {
                        query,
                        home,
                        checkpoint_limits,
                    },
                }),
            },
            CloseCustody::QueryRetirement {
                query,
                home,
                cause: _,
            } => retirement::advance(query, home, request),
            CloseCustody::MaintenanceRetirement {
                query,
                home,
                cause: _,
            } => retirement::advance(query, home, request),
            CloseCustody::QueryReleased {
                cause: _,
                posture,
                retired_query,
            } => {
                let outcome = match posture {
                    ApplicationHomeClosePosture::RecoveryRequired(home) => {
                        home.try_release(request)
                    }
                    ApplicationHomeClosePosture::Serving(home) => home.close(request),
                };
                classify_released_query(outcome, retired_query)
            }
        }
    }
}

//! Explicit disposal keeps each actual Home close phase on refusal.
use super::{close::*, refusal::*, runtime::DirectoryHome};
use worth_execution::ExecutionRequest;
use worth_query_declaration::facade::application_schema::ApplicationSchemaComposition;
use worth_query_execution::facade::{
    application_home_integration::*, primary_graph::WorthQueryPrimaryGraphInstallationDenial,
};
use worth_store_application::*;

pub struct WorthQueryApplicationHomeOpeningClosed {
    outcome: Option<ApplicationHomeCloseOutcome>,
    retired_query:
        Option<worth_query_execution::facade::application_installation::WorthQueryRetiredHomeQuery>,
}
impl WorthQueryApplicationHomeOpeningClosed {
    pub fn directory_outcome(&self) -> Option<&ApplicationHomeCloseOutcome> {
        self.outcome.as_ref()
    }
    fn from_query_closed(closed: WorthQueryApplicationHomeClosed) -> Self {
        let (outcome, retired_query) = closed.into_parts();
        Self {
            outcome: Some(outcome),
            retired_query,
        }
    }
    pub fn reclaim(self) {
        let Self {
            outcome,
            retired_query,
        } = self;
        drop(outcome);
        if let Some(retired_query) = retired_query {
            retired_query.reclaim();
        }
    }
}
pub struct WorthQueryApplicationHomeOpeningCloseRefused<
    Schema: ApplicationSchemaComposition,
    Program,
> {
    custody: OpeningCloseCustody<Schema, Program>,
}
enum OpeningCloseCustody<Schema: ApplicationSchemaComposition, Program> {
    Unrecovered(UnrecoveredApplicationHomeCloseRefused),
    Unshared(UnsharedApplicationHomeCloseRefused),
    World {
        query: WorldQueryPreparation<Schema, Program>,
        home: WorldHomeCloseRefused<(), (), (), (), ()>,
    },
    ReleasedQuery(WorthQueryApplicationHomeCloseRefused<Schema, Program>),
}
mod preparation;
mod retirement_plan;
use preparation::*;
impl<Schema: ApplicationSchemaComposition, Program: 'static>
    WorthQueryApplicationHomeOpenRefused<Schema, Program>
{
    pub fn close(
        self,
        request: &ExecutionRequest<'_, '_>,
    ) -> Result<
        WorthQueryApplicationHomeOpeningClosed,
        WorthQueryApplicationHomeOpeningCloseRefused<Schema, Program>,
    > {
        retirement_plan::prepare(self).execute(request)
    }
}

fn close_unrecovered<Schema: ApplicationSchemaComposition, Program>(
    home: UnrecoveredApplicationHome,
    request: &ExecutionRequest<'_, '_>,
) -> Result<
    WorthQueryApplicationHomeOpeningClosed,
    WorthQueryApplicationHomeOpeningCloseRefused<Schema, Program>,
> {
    match home.close(request) {
        Ok(outcome) => classify_released(outcome),
        Err(home) => Err(WorthQueryApplicationHomeOpeningCloseRefused {
            custody: OpeningCloseCustody::Unrecovered(home),
        }),
    }
}
fn close_unshared<Schema: ApplicationSchemaComposition, Program>(
    home: UnsharedReadmittedApplicationHome,
    request: &ExecutionRequest<'_, '_>,
) -> Result<
    WorthQueryApplicationHomeOpeningClosed,
    WorthQueryApplicationHomeOpeningCloseRefused<Schema, Program>,
> {
    match home.close(request) {
        Ok(outcome) => classify_released(outcome),
        Err(home) => Err(WorthQueryApplicationHomeOpeningCloseRefused {
            custody: OpeningCloseCustody::Unshared(home),
        }),
    }
}
fn close_world_preparation<Schema: ApplicationSchemaComposition, Program>(
    query: WorldQueryPreparation<Schema, Program>,
    home: DirectoryHome,
    request: &ExecutionRequest<'_, '_>,
) -> Result<
    WorthQueryApplicationHomeOpeningClosed,
    WorthQueryApplicationHomeOpeningCloseRefused<Schema, Program>,
> {
    match home.seal_world(request) {
        Ok(home) => {
            drop(query);
            classify_released(home.finish_close(request))
        }
        Err(home) => Err(WorthQueryApplicationHomeOpeningCloseRefused {
            custody: OpeningCloseCustody::World { query, home },
        }),
    }
}
fn classify_released<Schema: ApplicationSchemaComposition, Program>(
    outcome: ApplicationHomeCloseOutcome,
) -> Result<
    WorthQueryApplicationHomeOpeningClosed,
    WorthQueryApplicationHomeOpeningCloseRefused<Schema, Program>,
> {
    super::close::classify_released_query(outcome, None)
        .map(WorthQueryApplicationHomeOpeningClosed::from_query_closed)
        .map_err(|home| WorthQueryApplicationHomeOpeningCloseRefused {
            custody: OpeningCloseCustody::ReleasedQuery(home),
        })
}
impl<Schema: ApplicationSchemaComposition, Program> std::fmt::Debug
    for WorthQueryApplicationHomeOpeningCloseRefused<Schema, Program>
{
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match &self.custody {
            OpeningCloseCustody::Unrecovered(home) => {
                f.debug_tuple("Unrecovered").field(home.reason()).finish()
            }
            OpeningCloseCustody::Unshared(home) => {
                f.debug_tuple("Unshared").field(home.reason()).finish()
            }
            OpeningCloseCustody::World { query, home } => f
                .debug_struct("World")
                .field("opening", &query.detail())
                .field("close", home.reason())
                .finish(),
            OpeningCloseCustody::ReleasedQuery(home) => home.fmt(f),
        }
    }
}
impl<Schema: ApplicationSchemaComposition, Program: 'static>
    WorthQueryApplicationHomeOpeningCloseRefused<Schema, Program>
{
    pub fn try_close(
        self,
        request: &ExecutionRequest<'_, '_>,
    ) -> Result<WorthQueryApplicationHomeOpeningClosed, Self> {
        match self.custody {
            OpeningCloseCustody::Unrecovered(home) => match home.try_close(request) {
                Ok(outcome) => classify_released(outcome),
                Err(home) => Err(Self {
                    custody: OpeningCloseCustody::Unrecovered(home),
                }),
            },
            OpeningCloseCustody::Unshared(home) => match home.try_close(request) {
                Ok(outcome) => classify_released(outcome),
                Err(home) => Err(Self {
                    custody: OpeningCloseCustody::Unshared(home),
                }),
            },
            OpeningCloseCustody::World { query, home } => match home.try_seal_world(request) {
                Ok(home) => {
                    drop(query);
                    classify_released(home.finish_close(request))
                }
                Err(home) => Err(Self {
                    custody: OpeningCloseCustody::World { query, home },
                }),
            },
            OpeningCloseCustody::ReleasedQuery(home) => home
                .try_close(request)
                .map(WorthQueryApplicationHomeOpeningClosed::from_query_closed)
                .map_err(|home| Self {
                    custody: OpeningCloseCustody::ReleasedQuery(home),
                }),
        }
    }
}

