        })
        .expect("one process authority")
    })
}

pub(crate) fn request(workers: usize, memory: u64, work: u64) -> LeaseRequest {
    LeaseRequest {
        policy: ExecutionRequestPolicy::new(
            ExecutionPosture::Automatic,
            DeterminismContract::CanonicalBitwise,
            ExecutionBudget::new(
                NonZeroUsize::new(workers).unwrap(),
                Some(memory),
                Some(work),
            ),
        ),
        deadline: None,
        cancellation: CancellationToken::new(),
    }
}

// Work and scheduling courts declare the contract they exercise, without an
// unrelated byte ceiling that can refuse before the kernel reaches that boundary.
pub(crate) fn accounted_request(workers: usize, work: u64) -> LeaseRequest {
    LeaseRequest {
        policy: ExecutionRequestPolicy::new(
            ExecutionPosture::Automatic,
            DeterminismContract::CanonicalBitwise,
            ExecutionBudget::new(NonZeroUsize::new(workers).unwrap(), None, Some(work)),
        ),
        deadline: None,
        cancellation: CancellationToken::new(),
    }
}

pub(crate) fn batch(values: &[u64], memory_each: u64) -> AdmittedBatch<u64> {
    let entries = values
        .iter()
        .enumerate()
        .map(|(index, value)| {
            (
                PartitionIdentity::new(index as u64 + 1),
                *value,
                memory_each,
                0,
            )
        })
        .collect();
    AdmittedBatch::try_admit(entries, 0).unwrap_or_else(|_| panic!("canonical fixture"))
}

