//! Bootstrap custody borrows the caller's actual request and native accounting scope.
use super::{
    advancement_denial, ExecutionRequest, ExecutionWorkCeiling, OpeningCustody,
    WorthQueryAdvancementDenial, WorthQueryBootstrapAdvancementPhase,
};

/// Borrow original execution for installation or recovery. Native nested scopes inherit
/// remaining work, cancellation and deadlines; no lease or allowance is opened here.
/// The callback owns completion/error precedence and any performed recovery custody.
/// A callback that ran keeps its result even if a nested pattern stopped, so the
/// opening cannot discard an acknowledged or deferred native owner.
///
/// ```compile_fail,E0521
/// use worth_query_execution::facade::{application_contribution::with_bootstrap_advancement_from_request,
///     provider_session::ExecutionRequest};
/// fn escape(request: ExecutionRequest<'_, '_>) {
///     let _escaped = with_bootstrap_advancement_from_request(request, |phase| phase);
/// }
/// ```
/// ```
/// use worth_query_execution::facade::{application_contribution::with_bootstrap_advancement_from_request,
///     provider_session::ExecutionRequest};
/// fn borrow(request: ExecutionRequest<'_, '_>) {
///     let _ = with_bootstrap_advancement_from_request(request, |phase| {
///         phase.execution_request().consult()
///     });
/// }
/// ```
/// Bootstrap custody stays on the thread holding OpeningCustody and the native meter.
/// ```compile_fail,E0277
/// use worth_query_execution::facade::{application_contribution::with_bootstrap_advancement_from_request,
///     provider_session::ExecutionRequest};
/// fn move_to_worker(request: ExecutionRequest<'_, '_>) {
///     let _ = with_bootstrap_advancement_from_request(request, |phase| {
///         std::thread::scope(|threads| { threads.spawn(move || phase.execution_request().consult()); });
///     });
/// }
/// ```
pub fn with_bootstrap_advancement_from_request<R>(
    request: ExecutionRequest<'_, '_>,
    body: impl for<'scope> FnOnce(WorthQueryBootstrapAdvancementPhase<'scope>) -> R,
) -> Result<R, WorthQueryAdvancementDenial> {
    worth_execution::run_with_execution_stack(move || with_bootstrap_advancement_from_request_on_execution_stack(request, body))
}

#[inline(never)]
fn with_bootstrap_advancement_from_request_on_execution_stack<R>(
    request: ExecutionRequest<'_, '_>,
    body: impl for<'scope> FnOnce(WorthQueryBootstrapAdvancementPhase<'scope>) -> R,
) -> Result<R, WorthQueryAdvancementDenial> {
    let _custody = OpeningCustody::enter()?;
    request.consult().map_err(advancement_denial)?;
    let mut unwind = None;
    let mut value = None;
    // Nested execution carries only unit; the opening owner retains completion.
    let outcome = request.run(ExecutionWorkCeiling::new(request.work_ceiling()), |_| {
        if let Err(payload) = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            value = Some(body(WorthQueryBootstrapAdvancementPhase::new(request)));
        })) {
            unwind = Some(payload);
        }
    });
    if let Some(payload) = unwind {
        std::panic::resume_unwind(payload);
    }
    outcome
        .map(|((), _)| value.expect("completed bootstrap callback returned its value"))
        .map_err(advancement_denial)
}

//! Installed runtime owners lend one branded request for each public call.
use super::*;

impl<Schema: ApplicationSchema> WorthQueryPrimaryGraphApplicationRuntime<Schema> {
    pub fn with_host_advancement<R>(
        &self,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        worth_execution::run_with_execution_stack(move || self.with_host_advancement_on_execution_stack(body))
    }

    #[inline(never)]
    fn with_host_advancement_on_execution_stack<R>(
        &self,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        let _custody = OpeningCustody::enter()?;
        self.runtime
            .product_runtime
            .with_execution_placement(|placement| {
                let execution = QueryRequestExecution::open_control(
                    placement,
                    worth_execution::CancellationToken::new(),
                    None,
                );
                execution.run_product_advancement(&self.runtime.product_runtime, body)
            })?
    }

    /// Runs one host call funded as `allocation_policy` says. Under
    /// `Execution(lease)` the call's budget is a controlled child of `lease`,
    /// so every worker descends from it and the caller's charges stay inside
    /// one budget; any other lease is unrelated to those workers and refuses
    /// `UnrelatedNestedLease`. `SystemAllocation` uses the World's placement.
    pub fn with_funded_host_advancement<R>(
        &self,
        allocation_policy: worth_execution::ExecutionAllocationPolicy<'_, '_>,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        worth_execution::run_with_execution_stack(move || self.with_funded_host_advancement_on_execution_stack(allocation_policy, body))
    }

    #[inline(never)]
    fn with_funded_host_advancement_on_execution_stack<R>(
        &self,
        allocation_policy: worth_execution::ExecutionAllocationPolicy<'_, '_>,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        self.open_funded(
            allocation_policy,
            worth_execution::CancellationToken::new(),
            None,
            body,
        )
    }

    /// [`Self::with_application_advancement`] funded as `allocation_policy`
    /// says, under the request's cancellation and deadline. A lane that takes
    /// the caller's allocation policy opens through this, so `Execution(lease)`
    /// is the call's one budget rather than a second one inside the World's.
    pub fn with_funded_application_advancement<R>(
        &self,
        request: &WorthQueryRequestScope,
        allocation_policy: worth_execution::ExecutionAllocationPolicy<'_, '_>,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        worth_execution::run_with_execution_stack(move || self.with_funded_application_advancement_on_execution_stack(request, allocation_policy, body))
    }

    #[inline(never)]
    fn with_funded_application_advancement_on_execution_stack<R>(
        &self,
        request: &WorthQueryRequestScope,
        allocation_policy: worth_execution::ExecutionAllocationPolicy<'_, '_>,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        match allocation_policy {
            worth_execution::ExecutionAllocationPolicy::SystemAllocation => {
                self.with_application_advancement(request, body)
            }
            worth_execution::ExecutionAllocationPolicy::Execution(_) => self.open_funded(
                allocation_policy,
                request.cancellation().execution_token(),
                request.deadline(),
                body,
            ),
        }
    }

    fn open_funded<R>(
        &self,
        allocation_policy: worth_execution::ExecutionAllocationPolicy<'_, '_>,
        cancellation: worth_execution::CancellationToken,
        deadline: Option<worth_execution::MonotonicDeadline>,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        let _custody = OpeningCustody::enter()?;
        self.runtime
            .product_runtime
            .with_execution_placement(|placement| {
                let execution = match allocation_policy {
                    worth_execution::ExecutionAllocationPolicy::SystemAllocation => {
                        QueryRequestExecution::open_control(placement, cancellation, deadline)
                    }
                    worth_execution::ExecutionAllocationPolicy::Execution(lease) => {
                        QueryRequestExecution::under_lease(lease, cancellation, deadline)
                    }
                };
                execution.run_product_advancement(&self.runtime.product_runtime, body)
            })?
    }

    /// Checks borrowed advancement custody before a Publication entry reader.
    pub fn validate_application_advancement(
        &self,
        phase: &WorthQueryAdvancementPhase<'_>,
    ) -> Result<(), WorthQueryForeignAdvancementPhase> {
        phase
            .execution_request_for(&self.runtime.product_runtime)
            .map(|_| ())
    }

    /// The higher-ranked callback prevents a phase from escaping in its result.
    /// Custody covers the host call and its descendant workers; unrelated calls own theirs.
    /// Zero memory reports `PolicyMemoryLimit` in serial placement and a policy
    /// `MemoryLimit` in leased placement; both refuse before any read.
    pub fn with_application_advancement<R>(
        &self,
        request: &WorthQueryRequestScope,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        worth_execution::run_with_execution_stack(move || self.with_application_advancement_on_execution_stack(request, body))
    }

    #[inline(never)]
    fn with_application_advancement_on_execution_stack<R>(
        &self,
        request: &WorthQueryRequestScope,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        let _custody = OpeningCustody::enter()?;
        self.runtime
            .product_runtime
            .with_execution_placement(|placement| {
                let execution = QueryRequestExecution::open(placement, request);
                execution.run_product_advancement(&self.runtime.product_runtime, body)
            })?
    }
}

impl crate::domain_computation::execution_runtime::product_world::WorthQueryProductRuntime {
    /// Runs one host call inside the installed World's request policy.
    /// Custody follows the owner into descendant workers; unrelated calls own theirs.
    /// Zero memory is `PolicyMemoryLimit` at serial placement and a policy
    /// `MemoryLimit` at leased placement, before the callback begins.
    pub fn with_advancement<R>(
        &self,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        worth_execution::run_with_execution_stack(move || self.with_advancement_on_execution_stack(body))
    }

    #[inline(never)]
    fn with_advancement_on_execution_stack<R>(
        &self,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        self.open_host_advancement(worth_execution::CancellationToken::new(), None, body)
    }

    /// Runs a scoped host call under this installed World's policy and the
    /// caller's cancellation and deadline, lending only its branded phase.
    pub fn with_request_advancement<R>(
        &self,
        request: &WorthQueryRequestScope,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        worth_execution::run_with_execution_stack(move || self.with_request_advancement_on_execution_stack(request, body))
    }

    #[inline(never)]
    fn with_request_advancement_on_execution_stack<R>(
        &self,
        request: &WorthQueryRequestScope,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        self.open_host_advancement(
            request.cancellation().execution_token(),
            request.deadline(),
            body,
        )
    }

    fn open_host_advancement<R>(
        &self,
        cancellation: worth_execution::CancellationToken,
        deadline: Option<worth_execution::MonotonicDeadline>,
        body: impl for<'scope> FnOnce(WorthQueryAdvancementPhase<'scope>) -> R,
    ) -> Result<R, WorthQueryAdvancementDenial> {
        let _custody = OpeningCustody::enter()?;
        self.with_execution_placement(|placement| {
            QueryRequestExecution::open_control(placement, cancellation, deadline)
                .run_product_advancement(self, body)
        })?
    }
}

