        expected: &AdmittedSignalBranchBasis,
    ) -> Result<(), SignalBranchAdvanceDenial> {
        if !publication.admits_predecessor(expected) {
            return Err(SignalBranchAdvanceDenial::ConditionalDefinitionPublicationMismatch);
        }
        let owner = self
            .upgrade_owner()
            .map_err(SignalBranchAdvanceDenial::OwnerUnavailable)?;
        let admission = owner.admit().map_err(map_advance_admission_denial)?;
        let branch_id = expected.owner_branch_id();
        let cell = owner
            .lookup_cell(&admission, branch_id)
            .map_err(|denial| map_advance_registry_denial(denial, branch_id))?;
        if publication.incarnation() != cell.incarnation() {
            return Err(SignalBranchAdvanceDenial::ConditionalDefinitionPublicationMismatch);
        }
        Ok(())
    }

    /// Exact definition publication is reachable only through the dedicated
    /// non-cloneable Runtime World port.
    pub(in crate::branch::owner_services) fn advance_conditional_definition_exact_with_completion<
        F,
    >(
        &self,
        execution: worth_execution::ExecutionRequest<'_, '_>,

        publication: &mut Option<
            super::conditional_execution::SignalConditionalDefinitionPublicationOperation,
        >,
        expected: &AdmittedSignalBranchBasis,
        runtime_ctx: &mut Ctx,
        cancellation: &SignalOwnerCancellationToken,
        apply: F,
    ) -> crate::branch::SignalBranchAdvanceCompletion
    where
        F: FnOnce(&mut SignalTransaction<'_, D, I, E, Ctx, T>) -> Result<(), SignalError>,
    {
        use crate::branch::SignalBranchAdvanceCompletion;
        let execution = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let admitted = publication
                .as_ref()
                .expect("the original publication remains admitted");
            self.validate_conditional_definition_publication(admitted, expected)?;
            let owner = self
                .upgrade_owner()
                .map_err(SignalBranchAdvanceDenial::OwnerUnavailable)?;
            let admission = owner.admit().map_err(map_advance_admission_denial)?;
            let branch_id = expected.owner_branch_id();
            let cell = owner
                .lookup_cell(&admission, branch_id)
                .map_err(|denial| map_advance_registry_denial(denial, branch_id))?;
            if admitted.incarnation() != cell.incarnation() {
                return Err(SignalBranchAdvanceDenial::ConditionalDefinitionPublicationMismatch);
            }
            let output = owner.reserve_advance_output(&admission, &cell)?;
            Ok(output.advance_conditional_definition(
                execution,
                expected,
                runtime_ctx,
                cancellation,
                apply,
                publication,
            ))
        }));
        match execution {
            Ok(Ok(completion)) => completion,
            Ok(Err(denial)) => SignalBranchAdvanceCompletion::returned(Err(denial)),
            Err(payload) => SignalBranchAdvanceCompletion::unwound(None, payload),
        }
    }

    pub fn capture_exact(
        &self,
        expected: &AdmittedSignalBranchBasis,
        cancellation: &SignalOwnerCancellationToken,
    ) -> Result<SignalBranchSnapshotCaptureOutcome, SignalBranchSnapshotCaptureDenial> {
        let owner = self
            .upgrade_owner()
            .map_err(SignalBranchSnapshotCaptureDenial::OwnerUnavailable)?;
        let admission = owner.admit().map_err(map_capture_admission_denial)?;
        let branch_id = expected.owner_branch_id();
        let cell = owner
            .lookup_cell(&admission, branch_id)
            .map_err(|denial| map_capture_registry_denial(denial, branch_id))?;
        owner
            .reserve_snapshot_outputs(&admission, &cell)?
            .capture(expected, cancellation)
            .map(|ready| ready.into_outcome())
    }

    pub fn restore_exact(
        &self,
        expected: &AdmittedSignalBranchBasis,
        snapshot: &AdmittedSignalBranchSnapshot,
        cancellation: &SignalOwnerCancellationToken,
    ) -> Result<AdmittedSignalBranchBasis, SignalBranchRestoreDenial> {
        let owner = self
            .upgrade_owner()
            .map_err(SignalBranchRestoreDenial::OwnerUnavailable)?;
        let admission = owner.admit().map_err(map_restore_admission_denial)?;
        let branch_id = expected.owner_branch_id();
        let cell = owner
            .lookup_cell(&admission, branch_id)
            .map_err(|denial| map_restore_registry_denial(denial, branch_id))?;
        owner
            .reserve_restore_output(&admission, &cell)?
            .restore(expected, snapshot, cancellation)
            .map(|ready| ready.into_basis())
    }

    pub(super) fn upgrade_owner(
        &self,
    ) -> Result<Arc<SignalOwner<D, I, T>>, SignalOwnerUnavailable> {
        SignalOwner::upgrade(&self.owner)
    }
}

use crate::branch::{
    AdmittedSignalBranchBasis, SignalBranchAdvanceCompletion, SignalBranchAdvanceDenial,
};
use crate::data::error::SignalError;
use crate::logic::transaction::SignalTransaction;

use super::{
    SignalBranchMutationPort, SignalConditionalDefinitionPublicationOperation,
    SignalOwnerCancellationToken,
};

/// The non-cloneable Signal capability reserved for Runtime World definition publication.
/// Ordinary component service bundles never contain this port.
pub struct SignalConditionalDefinitionPublicationPort<D, I, E, Ctx, T>
where
    D: Copy + Ord + std::fmt::Debug + 'static,
    I: Copy + Ord,
    T: Copy + Ord,
{
    mutation: SignalBranchMutationPort<D, I, E, Ctx, T>,
}

/// A publication operation admitted against the exact Signal predecessor before
/// either component owner is allowed to move.
pub struct AdmittedSignalConditionalDefinitionPublication {
    operation: SignalConditionalDefinitionPublicationOperation,
}

impl<D, I, E, Ctx, T> SignalConditionalDefinitionPublicationPort<D, I, E, Ctx, T>
where
    D: Copy + Ord + std::fmt::Debug + 'static,
    I: Copy + Ord,
    T: Copy + Ord,
{
    pub(crate) fn new(mutation: SignalBranchMutationPort<D, I, E, Ctx, T>) -> Self {
        Self { mutation }
    }

    pub fn admit(
        &self,
        operation: SignalConditionalDefinitionPublicationOperation,
        expected: &AdmittedSignalBranchBasis,
    ) -> Result<AdmittedSignalConditionalDefinitionPublication, SignalBranchAdvanceDenial> {
        self.mutation
            .validate_conditional_definition_publication(&operation, expected)?;
        Ok(AdmittedSignalConditionalDefinitionPublication { operation })
    }

    /// Returns the original admitted permit when no canonical movement consumed it.
    /// Secure that custody before inspecting completion or resuming its unwind.
    pub fn advance_exact_with_completion<F>(
        &self,
        execution: worth_execution::ExecutionRequest<'_, '_>,

        admitted: AdmittedSignalConditionalDefinitionPublication,
        expected: &AdmittedSignalBranchBasis,
        runtime_ctx: &mut Ctx,
        cancellation: &SignalOwnerCancellationToken,
        apply: F,
    ) -> (
        SignalBranchAdvanceCompletion,
        Option<AdmittedSignalConditionalDefinitionPublication>,
    )
    where
        F: FnOnce(&mut SignalTransaction<'_, D, I, E, Ctx, T>) -> Result<(), SignalError>,
    {
        worth_execution::run_with_execution_stack(move || self.advance_exact_with_completion_on_execution_stack(execution, admitted, expected, runtime_ctx, cancellation, apply))
    }

    #[inline(never)]
    fn advance_exact_with_completion_on_execution_stack<F>(
        &self,
        execution: worth_execution::ExecutionRequest<'_, '_>,

        admitted: AdmittedSignalConditionalDefinitionPublication,
        expected: &AdmittedSignalBranchBasis,
        runtime_ctx: &mut Ctx,
        cancellation: &SignalOwnerCancellationToken,
        apply: F,
    ) -> (
        SignalBranchAdvanceCompletion,
        Option<AdmittedSignalConditionalDefinitionPublication>,
    )
    where
        F: FnOnce(&mut SignalTransaction<'_, D, I, E, Ctx, T>) -> Result<(), SignalError>,
    {
        let mut operation = Some(admitted.operation);
        let completion = self
            .mutation
            .advance_conditional_definition_exact_with_completion(
                execution,
                &mut operation,
                expected,
                runtime_ctx,
                cancellation,
                apply,
            );
        (
            completion,
            operation.map(|operation| AdmittedSignalConditionalDefinitionPublication { operation }),
        )
    }
}

