struct DropObservation(Rc<Cell<usize>>);
impl Drop for DropObservation {
    fn drop(&mut self) {
        self.0.set(self.0.get() + 1);
    }
}

#[test]
fn execution_stack_unwind_drops_the_original_callback_value_once() {
    let drops = Rc::new(Cell::new(0));
