    schema_with_binding!(
        wrong_identity,
        WrongIdentityBinding,
        "worth.query.certification.foreign-length.v1",
        Metre,
        "Metre"
    );
    schema_with_binding!(
        wrong_unit,
        WrongUnitBinding,
        "worth.query.certification.length.v1",
